<template><div class="cartbar"><div><b>购物车</b><small>{{count}} 件　合计 ¥{{total.toLocaleString()}}</small></div><button :disabled="count===0||!open" @click="$router.push({path:'/checkout',query:{storeId}})">{{open?'查看订单 →':'暂停接单'}}</button></div></template><script setup lang="ts">import {computed} from 'vue';import {cart,count} from '../cart';import type {Product} from '../api';const props=withDefaults(defineProps<{products:Product[];open?:boolean;storeId:string}>(),{open:true});const total=computed(()=>props.products.reduce((n,p)=>n+p.price*(cart[p.id]||0),0));</script>
